insert into glossary (id, term, plain_english, analogy) values ('marketCap', 'Market capitalisation', 'The total value of all a company''s shares added together. It''s a quick way to gauge how big the company is.', 'If a company had 100 shares worth ₹50 each, its market cap would be ₹5,000.');
insert into glossary (id, term, plain_english, analogy) values ('peRatio', 'Price-to-earnings (P/E) ratio', 'How much you pay for each ₹1 of the company''s yearly profit. A higher number means the share price is high compared with current profits, often because investors expect profits to grow.', 'A P/E of 25 means you pay ₹25 for every ₹1 the company earns in a year.');
insert into glossary (id, term, plain_english, analogy) values ('pbRatio', 'Price-to-book (P/B) ratio', 'The share price compared with the company''s net worth on paper (what it owns minus what it owes). It hints at how much extra investors are paying above the accounting value.', 'A P/B of 3 means the market values the company at three times what its books say it is worth.');
insert into glossary (id, term, plain_english, analogy) values ('dividendYield', 'Dividend yield', 'The yearly dividend a company pays out, shown as a percentage of its share price. It shows how much cash income the shares currently return.', 'A 2% yield means ₹2 paid out per year for every ₹100 of share price.');
insert into glossary (id, term, plain_english, analogy) values ('roe', 'Return on equity (ROE)', 'How much profit the company makes for every ₹1 that shareholders have put in or left in the business. Higher usually means the company uses its money efficiently.', 'An ROE of 18% means the company turned ₹100 of shareholder money into ₹18 of profit in a year.');
insert into glossary (id, term, plain_english, analogy) values ('debtToEquity', 'Debt-to-equity ratio', 'How much the company has borrowed compared with the money shareholders have in it. Higher means more reliance on loans, which adds risk if business slows.', 'A ratio of 0.5 means ₹0.50 of debt for every ₹1 of shareholder money.');
insert into glossary (id, term, plain_english, analogy) values ('revenueGrowth', 'Revenue growth (year on year)', 'How much the company''s total sales changed compared with the same period a year earlier, as a percentage.', 'If sales went from ₹100 crore to ₹112 crore, revenue growth is 12%.');
insert into glossary (id, term, plain_english, analogy) values ('profitMargin', 'Net profit margin', 'The share of each ₹100 of sales that the company keeps as profit after all costs and taxes.', 'A 15% margin means ₹15 of profit for every ₹100 of sales.');
insert into glossary (id, term, plain_english, analogy) values ('eps', 'Earnings per share (EPS)', 'The company''s yearly profit divided by the number of shares. It shows the profit that belongs to one share.', '₹500 crore of profit spread across 50 crore shares is an EPS of ₹10.');
insert into glossary (id, term, plain_english, analogy) values ('week52Range', '52-week range', 'The lowest and highest price the share has traded at over the past year. It gives a sense of how much the price moves.', 'A range of ₹800–₹1,200 means the share has swung between those two prices in the last year.');
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('RELIANCE', '2026-06-30', false, '{"whatItDoes":"Reliance earns money from three main areas: refining crude oil into fuels and chemicals, the Jio telecom and broadband network, and Reliance Retail''s chain of stores. The oil-to-chemicals business is the oldest; telecom and retail have grown fast over the last decade.","financialHealth":"Revenue is large and still growing at a high-single-digit pace. Profit margins are modest because refining is a low-margin business, and the company carries a fair amount of debt from building out Jio and retail. Cash from day-to-day operations comfortably covers its interest costs.","thingsToWatch":["Refining profits move with global oil and fuel prices, which Reliance does not control.","Debt is large in absolute terms, though it has come down from its peak.","Future growth leans heavily on telecom price rises and retail store expansion."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹19.7 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"24.8","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"2.1","standing":"typical"},{"id":"roe","label":"Return on equity","value":"8.9%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.44","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.4%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"7.6%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"8.1%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('TCS', '2026-06-30', false, '{"whatItDoes":"TCS is India''s largest IT services company. It writes software, runs and maintains technology systems, and provides consulting for large companies around the world, especially banks, retailers and manufacturers. Most of its revenue comes from the US and Europe and is billed in foreign currencies.","financialHealth":"TCS is highly profitable, keeps very little debt, and turns most of its profit into cash. Growth has slowed to low single digits recently as client spending on new projects softened. It returns a large share of profit to shareholders through dividends and buybacks.","thingsToWatch":["Revenue depends on technology budgets at Western banks and retailers, which shrink when their economies slow.","A stronger rupee reduces the value of overseas earnings when converted back home.","Growth has cooled from the double digits seen a few years ago."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹14.2 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"26.1","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"12.4","standing":"high"},{"id":"roe","label":"Return on equity","value":"47%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.09","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"3.1%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"4.2%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"19.4%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('HDFCBANK', '2026-06-30', false, '{"whatItDoes":"HDFC Bank is India''s largest private-sector bank. It takes deposits from savers and lends to individuals and businesses through home loans, car loans, credit cards and working-capital loans. It earns mainly from the gap between the interest it charges borrowers and the interest it pays depositors, plus fees.","financialHealth":"The bank is consistently profitable with a low share of bad loans. After merging with its parent housing-finance company in 2023, it has been working to grow deposits fast enough to fund its loan book. Return on equity is solid but has dipped slightly since the merger.","thingsToWatch":["Loan growth now depends on how quickly the bank can attract new deposits.","A weak economy can push up missed loan payments.","The 2023 merger is still being absorbed, which affects profit margins."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹13.6 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"18.9","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"2.7","standing":"typical"},{"id":"roe","label":"Return on equity","value":"16.1%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.1%","standing":"typical"},{"id":"revenueGrowth","label":"Net interest income growth (YoY)","value":"9.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"24.8%","standing":"high"},{"id":"eps","label":"Earnings per share","value":"₹88.3","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('INFY', '2026-06-30', false, '{"whatItDoes":"Infosys is a global IT services company and India''s second-largest. It builds custom software, moves clients onto cloud systems, and runs their technology operations. As with its peers, most revenue comes from large companies in the US and Europe.","financialHealth":"Infosys is very profitable with almost no debt and strong cash generation. Growth has slowed recently but held up a little better than some rivals. It returns most of its surplus cash to shareholders through dividends and buybacks.","thingsToWatch":["Demand is tied to technology budgets at Western firms.","Wage rises and a stronger rupee can squeeze profit margins.","Large contract wins can be lumpy from one quarter to the next."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹6.4 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"24.0","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"7.9","standing":"high"},{"id":"roe","label":"Return on equity","value":"31.8%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.09","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"2.6%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"6.1%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"17.2%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ITC', '2026-06-30', false, '{"whatItDoes":"ITC makes most of its profit from cigarettes, where it is the market leader in India. It has also built large packaged-foods brands such as Aashirvaad atta, Sunfeast biscuits and Bingo snacks, and it runs paperboard and agri-trading businesses.","financialHealth":"ITC is very profitable and almost debt-free, helped by the high margins on cigarettes. The foods business is growing but earns much thinner margins. The company pays out most of its profit as dividends, giving it one of the higher yields in the index.","thingsToWatch":["Cigarette profits depend heavily on how much tax the government adds each year.","The non-cigarette businesses earn far lower margins, so the overall profit mix shifts slowly.","The hotels business was recently separated into its own listed company."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹5.6 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"25.3","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"7.1","standing":"low"},{"id":"roe","label":"Return on equity","value":"28.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.00","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"3.4%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"5.7%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"24.1%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('MARUTI', '2026-06-30', false, '{"whatItDoes":"Maruti Suzuki is India''s largest carmaker, selling roughly two in every five new passenger vehicles. Its range runs from small hatchbacks like the Swift and Alto to SUVs like the Brezza and Grand Vitara. It is majority-owned by Japan''s Suzuki Motor Corporation.","financialHealth":"Maruti is profitable and carries virtually no debt, with a large pile of cash and investments. Margins improved as it sold more SUVs and as raw-material costs eased. Its main soft spot has been a smaller presence in electric vehicles than some rivals.","thingsToWatch":["Sales are sensitive to interest rates and fuel prices, which affect what buyers can afford.","The shift to electric cars is an area where Maruti started later than some competitors.","Steel and aluminium prices feed directly into the cost of each car."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.9 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"27.6","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"4.4","standing":"typical"},{"id":"roe","label":"Return on equity","value":"16.8%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.01","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.2%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"8.9%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"9.3%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ICICIBANK', '2026-06-30', false, '{"whatItDoes":"ICICI Bank is India''s second-largest private-sector bank. It lends to individuals (home, car and personal loans, credit cards) and to businesses, and earns mainly from the gap between the interest it charges and the interest it pays, plus fees from payments and wealth management.","financialHealth":"The bank has been one of the more profitable large lenders, with return on equity in the high teens and a low share of bad loans. Loan and deposit growth has been steady, and fee income adds a cushion when lending margins tighten.","thingsToWatch":["Unsecured loans such as personal loans and credit cards have grown quickly and are more prone to defaults if the economy weakens.","Competition for deposits across banks can push up funding costs.","A large retail loan book means results track household borrowing demand closely."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹9.8 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"17.2","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"3.1","standing":"typical"},{"id":"roe","label":"Return on equity","value":"17.8%","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"0.8%","standing":"typical"},{"id":"revenueGrowth","label":"Net interest income growth (YoY)","value":"12.6%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"26.4%","standing":"high"},{"id":"eps","label":"Earnings per share","value":"₹64.5","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('SBIN', '2026-06-30', false, '{"whatItDoes":"State Bank of India is the country''s largest bank and is majority-owned by the government. It has the widest branch and ATM network in India, a very large deposit base, and lends across retail, farm and corporate segments. It also holds stakes in listed insurance, mutual fund and card businesses.","financialHealth":"Profits have improved as older bad loans were cleaned up, and return on equity has moved into the mid-teens. A very large, low-cost deposit base is a structural advantage. As a government-owned bank, it sometimes carries policy goals alongside commercial ones.","thingsToWatch":["As a government bank, it can be asked to support national schemes that may not be the most profitable use of its capital.","Corporate lending cycles have historically caused spikes in bad loans.","The value of its insurance and other subsidiaries is a meaningful part of the overall picture."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹7.6 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"9.8","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"1.7","standing":"low"},{"id":"roe","label":"Return on equity","value":"15.3%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.6%","standing":"high"},{"id":"revenueGrowth","label":"Net interest income growth (YoY)","value":"10.1%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"22.1%","standing":"typical"},{"id":"eps","label":"Earnings per share","value":"₹78.2","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('KOTAKBANK', '2026-06-30', false, '{"whatItDoes":"Kotak Mahindra Bank is a mid-sized private-sector bank known for conservative lending and a strong presence in wealth management, broking and asset management through its subsidiaries. It has historically prioritised profitability and asset quality over rapid growth.","financialHealth":"The bank runs with high capital levels, a low share of bad loans and healthy return on equity. Growth has generally been slower than some private peers, partly by choice. Its non-bank businesses add a steady stream of fee income.","thingsToWatch":["A cautious approach can mean slower loan growth when rivals expand faster.","A past regulatory restriction on adding new digital customers showed how supervision can affect growth.","The transition after its long-time founder-CEO stepped back from the top job is still being watched."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.6 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"18.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"2.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"14.2%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.3%","standing":"low"},{"id":"revenueGrowth","label":"Net interest income growth (YoY)","value":"8.2%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"25.6%","standing":"high"},{"id":"eps","label":"Earnings per share","value":"₹92.1","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('AXISBANK', '2026-06-30', false, '{"whatItDoes":"Axis Bank is India''s third-largest private-sector bank. It offers the full range of retail and corporate banking, and has expanded in credit cards and digital payments, including after buying Citi''s India consumer business.","financialHealth":"Profitability has improved as the bank reduced problem corporate loans and grew higher-margin retail lending, lifting return on equity into the mid-teens. Integrating the acquired Citi customers has added costs in the short term.","thingsToWatch":["The Citi consumer business integration adds one-off costs and execution risk.","A sizeable corporate loan book leaves it exposed to business-cycle downturns.","Deposit growth needs to keep pace with its lending ambitions."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.7 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"13.6","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"2.1","standing":"low"},{"id":"roe","label":"Return on equity","value":"15.8%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.2%","standing":"low"},{"id":"revenueGrowth","label":"Net interest income growth (YoY)","value":"11.4%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"23.9%","standing":"typical"},{"id":"eps","label":"Earnings per share","value":"₹86.7","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('INDUSINDBK', '2026-06-30', false, '{"whatItDoes":"IndusInd Bank is a mid-sized private-sector bank with a strong position in vehicle financing (commercial vehicles, two-wheelers, tractors) and in microfinance through its Bharat Financial arm, alongside regular retail and corporate banking.","financialHealth":"The bank earns relatively high lending margins because vehicle and microfinance loans carry higher interest rates, but these segments also see more defaults in a downturn. Return on equity has been in the mid-teens in good years.","thingsToWatch":["Vehicle finance and microfinance are more cyclical and default-prone than home loans.","It has a higher share of bulk deposits, which are less sticky than retail deposits.","Past questions around loan classification have made investors more sensitive to its reporting."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.1 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"10.9","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"1.5","standing":"low"},{"id":"roe","label":"Return on equity","value":"14.6%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.4%","standing":"high"},{"id":"revenueGrowth","label":"Net interest income growth (YoY)","value":"13.8%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"20.3%","standing":"low"},{"id":"eps","label":"Earnings per share","value":"₹124.5","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('HCLTECH', '2026-06-30', false, '{"whatItDoes":"HCL Technologies is India''s third-largest IT services company. Alongside the usual software development and IT operations work, it has an unusually large engineering and R&D services arm (designing chips, devices and software for tech and industrial firms) and a smaller software-products business.","financialHealth":"HCLTech is solidly profitable with very little debt and steady cash generation. Growth has held up a little better than some peers, helped by its engineering-services mix. It pays out a high share of profit as dividends.","thingsToWatch":["The software-products business grows slowly and can drag on the overall growth rate.","Like all Indian IT, demand depends on technology budgets at large Western companies.","Engineering-services clients in areas like semiconductors and cars have their own cycles."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹4.6 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"25.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"6.2","standing":"typical"},{"id":"roe","label":"Return on equity","value":"23.6%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.08","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"3.6%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"5.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"16.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('WIPRO', '2026-06-30', false, '{"whatItDoes":"Wipro is one of India''s largest IT services companies, offering software development, cloud migration, consulting and IT operations for global clients. It has a large base of banking and financial-services clients and, after buying the consultancy Capco, a bigger front-end advisory business.","financialHealth":"Wipro is profitable with low debt, but revenue growth has trailed its larger rivals for several years and margins are a little lower. It returns cash through regular buybacks and dividends.","thingsToWatch":["Growth has lagged TCS, Infosys and HCLTech, and closing that gap has proven hard.","Heavy exposure to banking and financial-services clients means Western banking budgets matter a lot.","Frequent changes in senior leadership over recent years have unsettled strategy."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.7 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"22.1","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"3.6","standing":"low"},{"id":"roe","label":"Return on equity","value":"16.4%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.12","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"2.1%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"2.3%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"16.1%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('TECHM', '2026-06-30', false, '{"whatItDoes":"Tech Mahindra is an IT services company with an unusually large share of revenue from telecom operators, whom it helps run networks and billing systems, alongside standard software and IT work for other industries.","financialHealth":"Profit margins have been below the sector''s leaders and the company is midway through a plan to improve them. Debt is low and cash generation is adequate. Growth has been soft as telecom clients cut spending.","thingsToWatch":["Telecom customers have been spending cautiously, which hits Tech Mahindra more than diversified peers.","Its profit margins have room to improve, but the turnaround is still unproven.","Its record on past acquisitions has been mixed."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.5 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"31.5","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"4.1","standing":"low"},{"id":"roe","label":"Return on equity","value":"13.2%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.10","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"2.8%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"3.1%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"9.4%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('LTIM', '2026-06-30', false, '{"whatItDoes":"LTIMindtree is an IT services company formed in 2022 by merging Larsen & Toubro''s two listed software firms, L&T Infotech and Mindtree. It does software development, data and cloud work, and IT operations, with strong client bases in banking, insurance and technology.","financialHealth":"The company is profitable with negligible debt and good cash conversion. Growth has recently been closer to the sector average than to the top of the pack. The two merged businesses are still being fully integrated.","thingsToWatch":["Completing the integration of L&T Infotech and Mindtree (systems, teams, clients) is still in progress.","A concentrated set of large clients means losing one would be felt.","Demand depends on Western technology budgets, as for all Indian IT."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.6 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"29.8","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"5.9","standing":"typical"},{"id":"roe","label":"Return on equity","value":"22.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.05","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.9%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"6.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"14.6%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('TATAMOTORS', '2026-06-30', false, '{"whatItDoes":"Tata Motors makes passenger cars, trucks and buses in India and owns the British luxury carmaker Jaguar Land Rover, which brings in most of its revenue. In India it is the market leader in electric passenger cars and a major player in commercial vehicles.","financialHealth":"Profits have improved sharply as Jaguar Land Rover recovered and Indian commercial-vehicle demand held up. The company has cut what was once a very large debt pile close to zero on a net basis. Results still swing with the global luxury-car cycle.","thingsToWatch":["Jaguar Land Rover drives most of the profit, so European and Chinese luxury-car demand matters more than the Indian business.","Commercial-vehicle sales are closely tied to India''s economic and infrastructure cycle.","Heavy spending is needed on electric and cleaner models across both businesses."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.5 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"12.4","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"3.1","standing":"low"},{"id":"roe","label":"Return on equity","value":"22.6%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.35","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.1%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"11.2%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"7.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('MM', '2026-06-30', false, '{"whatItDoes":"Mahindra & Mahindra makes SUVs and is India''s largest tractor maker. Its SUV line-up (Thar, Scorpio-N, XUV700) has sold strongly in recent years. It also holds stakes in listed group companies in IT, finance and other areas.","financialHealth":"Both the SUV and tractor businesses have been profitable, and the company has tightened focus after exiting several loss-making ventures. Return on equity is healthy and debt in the core auto business is low. Tractor demand rises and falls with the farm economy.","thingsToWatch":["Tractor sales depend on monsoon rains, crop prices and rural incomes.","SUV demand has been strong, but competition in that segment is intense.","The value of its many listed and unlisted subsidiaries is a large part of the overall picture."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.6 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"24.8","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"4.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"18.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.12","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.9%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"12.6%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"10.6%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('BAJAJ-AUTO', '2026-06-30', false, '{"whatItDoes":"Bajaj Auto makes motorcycles and three-wheelers. It sells a large share of its output abroad, particularly in Africa, Latin America and South Asia, and owns a stake in Austria''s KTM. It also sells the Chetak electric scooter.","financialHealth":"Bajaj Auto runs some of the highest profit margins in the industry, holds a large cash pile and almost no debt, and returns a lot of cash to shareholders through dividends and buybacks. Exports give it a second demand engine alongside India.","thingsToWatch":["A big export business means currency swings and economic trouble in Africa or Latin America feed through to results.","It has been slower into electric two-wheelers than some newer rivals.","Domestic entry-level motorcycle demand has been patchy."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.6 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"31.2","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"8.4","standing":"high"},{"id":"roe","label":"Return on equity","value":"27.8%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.00","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.9%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"9.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"17.2%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('EICHERMOT', '2026-06-30', false, '{"whatItDoes":"Eicher Motors owns Royal Enfield, which dominates India''s mid-size motorcycle segment (250–750cc) with models like the Classic and Hunter, and holds a commercial-vehicle joint venture with Volvo. Royal Enfield drives most of the profit.","financialHealth":"Royal Enfield earns unusually high margins for a motorcycle business, and the company has little debt and strong cash generation. Growth depends on holding its niche as rivals launch competing mid-size bikes and on expanding Royal Enfield sales overseas.","thingsToWatch":["Royal Enfield faces new competition in the mid-size segment from Bajaj-Triumph, Harley-Hero and others.","The company is heavily reliant on one brand in one segment.","Overseas expansion is still a small part of sales."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.4 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"29.4","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"6.8","standing":"high"},{"id":"roe","label":"Return on equity","value":"23.6%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.01","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.3%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"10.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"19.4%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('HEROMOTOCO', '2026-06-30', false, '{"whatItDoes":"Hero MotoCorp is the world''s largest maker of motorcycles and scooters by volume, built on a dominant position in India''s mass-market commuter motorcycles. It is expanding into premium bikes (with Harley-Davidson) and electric scooters (Vida).","financialHealth":"Hero is highly profitable in its core commuter segment, holds net cash and pays generous dividends. The challenge is growth: commuter demand has been flat for years, and Hero is under-represented in the faster-growing scooter, premium and electric segments.","thingsToWatch":["Mass-market motorcycle demand in India has been broadly flat for several years.","Hero is weaker in scooters and premium bikes, where the market is growing faster.","The move into electric scooters is early and competitive."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹0.9 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"19.6","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"4.2","standing":"typical"},{"id":"roe","label":"Return on equity","value":"22.1%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.02","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"3.4%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"6.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"11.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('HINDUNILVR', '2026-06-30', false, '{"whatItDoes":"Hindustan Unilever is India''s largest consumer-goods company, owned by the global Unilever group. It sells everyday brands across home care (Surf Excel, Vim), personal care (Dove, Lux, Lifebuoy), and foods and refreshment (Brooke Bond, Bru, Horlicks, Kissan).","financialHealth":"The company earns very high returns on capital, carries no meaningful debt, and hands almost all its profit back as dividends. Growth comes from a mix of price and volume; in rural slowdowns, volume growth can stall for several quarters.","thingsToWatch":["Rural demand, a large share of sales, is sensitive to inflation and the monsoon.","Prices of inputs like palm oil, crude derivatives and tea move margins.","Smaller regional and direct-to-consumer brands are chipping away in some categories."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹5.8 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"52.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"11.2","standing":"typical"},{"id":"roe","label":"Return on equity","value":"20.6%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.03","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"2.1%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"4.6%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"16.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('NESTLEIND', '2026-06-30', false, '{"whatItDoes":"Nestlé India, a subsidiary of the Swiss group Nestlé, sells packaged foods and beverages: Maggi noodles and sauces, Nescafé coffee, KitKat and Munch chocolates, and infant nutrition brands like Cerelac and Lactogen.","financialHealth":"Nestlé India earns among the highest returns on capital in the market, helped by strong brands and an asset-light model. It has little debt and pays out most of its profit. Milk and cocoa prices are the main pressure on margins.","thingsToWatch":["A large share of sales comes from just a few brands, with Maggi the biggest single one.","Milk, coffee and cocoa prices feed directly into costs.","Its products sit at a price premium, which can be a drag when consumers trade down."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.4 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"58.6","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"38.4","standing":"high"},{"id":"roe","label":"Return on equity","value":"72.4%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.05","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.4%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"6.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"15.4%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('BRITANNIA', '2026-06-30', false, '{"whatItDoes":"Britannia Industries is one of India''s largest food companies, best known for biscuits (Good Day, Marie Gold, Bourbon, Milk Bikis). It also sells bread, cakes, rusk and a growing range of dairy products like cheese and milk drinks.","financialHealth":"Britannia is highly profitable for a food business, with strong brands and wide distribution. It carries modest debt and pays generous dividends. Wheat, sugar, palm oil and milk prices are the main swing factor for margins.","thingsToWatch":["Biscuits are a mature category in cities; most growth now has to come from rural areas and new products.","Commodity costs (wheat, palm oil, sugar) can move margins sharply.","The push into dairy and other adjacent categories is still building scale."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.4 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"52.8","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"26.4","standing":"high"},{"id":"roe","label":"Return on equity","value":"58.2%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.42","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.8%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"7.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"12.6%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('TATACONSUM', '2026-06-30', false, '{"whatItDoes":"Tata Consumer Products sells tea (Tata Tea, Tetley), Tata Salt, coffee (Eight O''Clock), pulses and spices (Tata Sampann), and packaged water. It runs the Starbucks coffee-shop joint venture in India and has been expanding from beverages into a broader food and staples business.","financialHealth":"Margins are thinner than at pure branded-foods peers because salt and tea are lower-margin staples, but the newer packaged-foods lines are helping the mix. Debt is moderate after recent acquisitions, and return on equity is in the low teens.","thingsToWatch":["Tea and salt are low-margin staples where pricing power is limited.","Recent acquisitions (Capital Foods, Organic India) need to be integrated and to earn their price.","Tea leaf prices can be volatile depending on the harvest."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.1 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"62.4","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"4.8","standing":"low"},{"id":"roe","label":"Return on equity","value":"9.4%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.18","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.1%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"9.8%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"9.2%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('SUNPHARMA', '2026-06-30', false, '{"whatItDoes":"Sun Pharmaceutical is India''s largest drugmaker. It sells generic medicines around the world, has the biggest branded-medicine business in India, and has been building a higher-margin specialty portfolio (skin, eye and other branded drugs) in the United States.","financialHealth":"Sun is profitable with low debt and strong cash generation. The shift toward specialty drugs has lifted margins above those of a typical generics maker. US generic price competition and the cost of running specialty sales teams are the main pressures.","thingsToWatch":["US generic prices have been under long-running pressure from consolidated buyers.","Specialty drugs need heavy marketing spend before they pay off.","Regulatory inspections of manufacturing plants can disrupt supply and sales."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹4.4 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"36.2","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"6.4","standing":"typical"},{"id":"roe","label":"Return on equity","value":"17.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.05","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.8%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"9.6%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"17.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('DRREDDY', '2026-06-30', false, '{"whatItDoes":"Dr. Reddy''s Laboratories makes generic medicines and the active ingredients that go into them, selling mainly in the United States, India, Russia and other emerging markets. It also has a small but growing biosimilars business and, after a recent acquisition, a consumer-health nicotine-replacement range.","financialHealth":"The company is profitable with low debt and a net cash position. Earnings depend heavily on how many high-value generic launches it lands in the US in a given year, which makes results lumpy. Margins are solid for a generics maker.","thingsToWatch":["US earnings swing with the timing of big generic launches and how fast prices then erode.","One product (a generic of a cancer drug) has contributed an outsized share of recent US profit.","Factory inspections by the US regulator are a recurring risk."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.1 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"18.6","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"3.2","standing":"low"},{"id":"roe","label":"Return on equity","value":"18.9%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.08","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.7%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"8.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"16.4%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('CIPLA', '2026-06-30', false, '{"whatItDoes":"Cipla is best known in India for respiratory medicines and inhalers, where it is the market leader, and has a strong presence in South Africa and other emerging markets. In the United States it sells generics and has been pushing into harder-to-copy respiratory and peptide products.","financialHealth":"Cipla is profitable with very low debt and a net cash balance sheet. Its large, steady India branded business gives it a more stable earnings base than a pure US generics maker. Growth now depends on landing complex US respiratory launches.","thingsToWatch":["Complex US launches (such as a generic of a major inhaler) have faced delays and regulatory hurdles.","Manufacturing-plant inspections by the US regulator have flagged issues in the past.","The South Africa business carries currency risk from the rand."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.3 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"24.8","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"3.8","standing":"low"},{"id":"roe","label":"Return on equity","value":"16.8%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.03","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.9%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"7.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"16.2%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('DIVISLAB', '2026-06-30', false, '{"whatItDoes":"Divi''s Laboratories does not sell finished medicines. It makes active pharmaceutical ingredients and intermediates in bulk for other drug companies — both large-volume generic ingredients and custom synthesis work for innovator drugmakers.","financialHealth":"Divi''s earns unusually high margins for a manufacturer, is debt-free and holds a large cash pile. Because it supplies other pharma companies, its sales rise and fall with their production and inventory cycles, which made recent years bumpy.","thingsToWatch":["Sales depend on a relatively small number of large pharma customers and their ordering patterns.","A handful of products account for a big share of revenue.","New capacity has been added ahead of demand, which weighs on returns until it fills up."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.6 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"42.6","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"7.8","standing":"high"},{"id":"roe","label":"Return on equity","value":"16.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.00","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.7%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"11.4%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"22.8%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('TATASTEEL', '2026-06-30', false, '{"whatItDoes":"Tata Steel is one of India''s largest steel producers, making steel for construction, cars and packaging. It also has big operations in the Netherlands and the UK, though the European business has struggled and is being restructured toward lower-carbon electric furnaces.","financialHealth":"The Indian operations are low-cost and profitable, while the European business has swung between small profits and losses. Steel is highly cyclical, so earnings move sharply with global prices. The company has been paying down a debt load built up from past acquisitions.","thingsToWatch":["Steel prices are set globally and swing with Chinese demand and exports.","The UK and Netherlands operations still need to prove they can make steady profits.","Coking coal and energy costs are large and volatile inputs."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.1 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"14.2","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"2.1","standing":"typical"},{"id":"roe","label":"Return on equity","value":"11.8%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.72","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"2.6%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"3.4%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"8.4%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('JSWSTEEL', '2026-06-30', false, '{"whatItDoes":"JSW Steel is India''s largest steelmaker by capacity, supplying construction, automotive and appliance customers. It has expanded aggressively through new plants and acquisitions and has smaller operations in the US and Italy.","financialHealth":"JSW runs efficient, large-scale plants and has grown faster than peers, but the constant capacity building keeps its debt relatively high. Profits rise and fall sharply with steel prices, and recent years have seen heavy investment ahead of demand.","thingsToWatch":["Debt stays elevated because the company keeps investing in new capacity.","Earnings are highly sensitive to steel prices and to iron ore and coking coal costs.","Cheap steel imports into India can pressure domestic prices."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.4 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"22.6","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"2.8","standing":"high"},{"id":"roe","label":"Return on equity","value":"12.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.98","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"1.1%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"5.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"6.8%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('HINDALCO', '2026-06-30', false, '{"whatItDoes":"Hindalco, part of the Aditya Birla group, makes aluminium and copper in India and owns Novelis, the world''s largest producer of rolled aluminium and aluminium recycling, which supplies beverage cans and car makers mainly in North America and Europe.","financialHealth":"Novelis provides a relatively steady stream of profit from cans and car parts, which cushions the more volatile India aluminium and copper businesses. Debt is moderate and has been coming down. Aluminium prices and energy costs are the main swing factors.","thingsToWatch":["The India aluminium business is exposed to global metal prices and to coal and power costs.","Novelis is investing heavily in new capacity and recycling, which raises spending in the near term.","Beverage-can demand in the US has at times been softer than expected."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.7 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"11.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"1.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"13.6%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.58","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.4%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"6.2%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"6.4%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('COALINDIA', '2026-06-30', false, '{"whatItDoes":"Coal India is the government-controlled company that mines about four-fifths of India''s coal, most of it sold to power stations. It is effectively a near-monopoly supplier of a fuel the country still relies on heavily for electricity.","financialHealth":"Coal India generates large, steady cash flows, carries very little debt, and pays one of the highest dividend yields in the market. Prices for a big share of its output are regulated, so earnings are more stable than for most commodity producers.","thingsToWatch":["Over the long term, the shift to renewable energy is a structural risk to coal demand.","As a government company, it can be directed to hold prices down or fund social spending.","Wage agreements with a large unionised workforce are a recurring cost pressure."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.6 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"7.8","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"2.8","standing":"high"},{"id":"roe","label":"Return on equity","value":"38.4%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.08","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"5.4%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"4.2%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"22.6%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ONGC', '2026-06-30', false, '{"whatItDoes":"ONGC is India''s largest producer of crude oil and natural gas, pumping most of the oil and gas the country produces domestically. It is majority government-owned and also controls the refiner HPCL and holds overseas oil and gas assets.","financialHealth":"ONGC generates large cash flows when oil prices are firm, and it carries moderate debt. Its realised prices can be capped by government measures when crude is high, and ageing fields mean it must keep spending heavily just to hold output steady.","thingsToWatch":["Earnings rise and fall with global crude oil and gas prices, which it does not control.","The government can impose windfall taxes or price caps when oil is expensive.","Domestic oil and gas output has been slowly declining, so large investment is needed to arrest it."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.4 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"7.4","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"0.9","standing":"low"},{"id":"roe","label":"Return on equity","value":"13.8%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.42","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"4.6%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"2.8%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"9.2%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('BPCL', '2026-06-30', false, '{"whatItDoes":"Bharat Petroleum refines crude oil and sells fuels through one of India''s largest networks of petrol pumps. It is government-owned, after a plan to privatise it was called off, and is investing in refinery expansion, petrochemicals and electric-vehicle charging.","financialHealth":"Profits swing widely: refining margins and fuel-marketing margins both move with crude prices and with how freely the company is allowed to change pump prices. In good years it generates strong cash and pays generous dividends; in bad years marketing losses can wipe out profit.","thingsToWatch":["Pump prices are influenced by the government, especially around elections, which can squeeze marketing margins when crude rises.","Refining margins are set by global product markets.","A large capital-spending programme will keep debt elevated for a few years."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.4 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"9.2","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"1.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"18.4%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.68","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"4.2%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"3.6%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"3.8%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('BAJFINANCE', '2026-06-30', false, '{"whatItDoes":"Bajaj Finance is India''s largest non-bank consumer lender. It finances purchases of phones, appliances and other goods at the point of sale, issues EMI cards, and gives personal, small-business and home loans to a customer base of around 90 million.","financialHealth":"The company has grown its loan book at a fast pace for many years while keeping bad loans low and return on equity high. That track record earns it one of the highest valuations among lenders. Growth this fast needs constant access to funding at reasonable rates.","thingsToWatch":["Very fast loan growth is hard to sustain, and any rise in defaults would be noticed quickly given the high valuation.","As a non-bank it relies on borrowing from banks and bond markets; if that funding gets costlier, margins narrow.","Regulators have tightened rules on digital and unsecured lending, where Bajaj is active."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹6.2 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"31.4","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"5.8","standing":"high"},{"id":"roe","label":"Return on equity","value":"21.6%","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"0.5%","standing":"low"},{"id":"revenueGrowth","label":"Loan book growth (YoY)","value":"26.4%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"24.2%","standing":"typical"},{"id":"eps","label":"Earnings per share","value":"₹315.6","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('BAJAJFINSV', '2026-06-30', false, '{"whatItDoes":"Bajaj Finserv is a holding company for the Bajaj group''s financial businesses. Its main assets are a majority stake in Bajaj Finance (consumer lending), a life insurer and a general insurer (both Bajaj Allianz), and some newer digital and health ventures.","financialHealth":"Most of its reported profit comes from consolidating Bajaj Finance, so its results move with that company. The two insurance businesses add steadier premium income. As a holding company, its market value tends to sit at a discount to the combined worth of its parts.","thingsToWatch":["Its fortunes are tied closely to Bajaj Finance, which drives the bulk of profit.","The general insurance business is exposed to natural-catastrophe claims in a bad year.","Holding companies often trade below the value of the businesses they own."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.2 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"34.8","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"4.2","standing":"typical"},{"id":"roe","label":"Return on equity","value":"13.8%","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.1%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"18.6%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"12.4%","standing":"low"},{"id":"eps","label":"Earnings per share","value":"₹58.4","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('SHRIRAMFIN', '2026-06-30', false, '{"whatItDoes":"Shriram Finance is a non-bank lender formed by merging the Shriram group''s truck-finance and retail-finance arms. It specialises in loans for commercial vehicles (especially used trucks bought by small operators), and also does two-wheeler, gold, small-business and personal loans.","financialHealth":"Lending to small truck operators and other underbanked borrowers carries higher interest rates and higher defaults than mainstream lending. The company has managed this niche for decades, earns a solid return on equity, and pays a healthy dividend. Funding cost is a key lever.","thingsToWatch":["Truck-finance demand is cyclical and tied to freight rates and the wider economy.","Its borrowers are more vulnerable in downturns, so bad loans can rise faster than at banks.","It depends on wholesale funding, so its borrowing costs matter a lot."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.2 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"13.2","standing":"low"},{"id":"pbRatio","label":"P/B ratio","value":"2.1","standing":"low"},{"id":"roe","label":"Return on equity","value":"16.4%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"1.6%","standing":"high"},{"id":"revenueGrowth","label":"Loan book growth (YoY)","value":"19.8%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"22.8%","standing":"typical"},{"id":"eps","label":"Earnings per share","value":"₹242.3","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('NTPC', '2026-06-30', false, '{"whatItDoes":"NTPC is India''s largest electricity generator, producing roughly a quarter of the country''s power, mostly from coal-fired plants. It is government-controlled and is expanding fast into solar and wind through its listed arm NTPC Green Energy.","financialHealth":"NTPC earns a regulated return on the money it invests in power plants, so its profits are fairly steady and predictable. It carries a lot of debt because building power stations is capital-heavy. It pays a reliable dividend.","thingsToWatch":["Earnings depend on regulators keeping the allowed return on equity broadly where it is.","Delays in payments from cash-strapped state electricity distribution companies can tie up cash.","The long-term shift away from coal means a large, ongoing pivot to renewables."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.5 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"14.6","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"1.9","standing":"typical"},{"id":"roe","label":"Return on equity","value":"13.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"1.42","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"2.4%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"7.2%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"12.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('POWERGRID', '2026-06-30', false, '{"whatItDoes":"Power Grid Corporation builds and runs most of India''s high-voltage transmission network — the long-distance lines that carry electricity between states. It is government-controlled and earns a regulated return on the assets it puts into service.","financialHealth":"Because its returns are regulated and its lines are always in use, Power Grid''s earnings are among the most stable of any large listed company. It funds its network with debt but services it comfortably, and it pays out a high share of profit as dividends.","thingsToWatch":["Growth depends on the pipeline of new transmission projects it wins, much of it now linked to connecting renewable energy.","A change in the regulated return on equity would move earnings.","Payment delays from state utilities can slow cash collection."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.8 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"16.8","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"2.9","standing":"high"},{"id":"roe","label":"Return on equity","value":"18.6%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"1.28","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"3.6%","standing":"high"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"5.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"32.4%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('HDFCLIFE', '2026-06-30', false, '{"whatItDoes":"HDFC Life is one of India''s largest private life insurers. It sells savings, investment-linked and protection policies, distributed heavily through HDFC Bank branches as well as its own agents and online.","financialHealth":"The company has grown new-business premiums steadily and focuses on the more profitable protection and non-participating products. Reported net profit is small relative to premiums, which is normal for life insurers, where value builds up over the life of each policy.","thingsToWatch":["A large share of sales comes through HDFC Bank, so any change in that relationship matters.","Tax and regulatory changes to insurance products can quickly shift what customers buy.","Standard accounting profit understates the business; measures like new-business value give a fuller picture."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.6 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"72.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"8.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"11.8%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.4%","standing":"typical"},{"id":"revenueGrowth","label":"New business premium growth (YoY)","value":"14.2%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"4.6%","standing":"typical"},{"id":"eps","label":"Earnings per share","value":"₹8.2","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('SBILIFE', '2026-06-30', false, '{"whatItDoes":"SBI Life is India''s largest private life insurer by premiums. It sells savings, unit-linked and protection policies, distributed mainly through the vast branch network of State Bank of India.","financialHealth":"SBI Life runs with one of the lowest cost ratios in the industry, helped by the low-cost SBI branch channel, and has grown premiums consistently. As with all life insurers, headline profit is modest next to premium income because value accrues over each policy''s life.","thingsToWatch":["It depends heavily on State Bank of India for distribution.","Its product mix leans more toward market-linked plans, whose sales fall when equity markets are weak.","Changes to how insurance products are taxed can shift demand sharply."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.7 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"68.6","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"8.9","standing":"typical"},{"id":"roe","label":"Return on equity","value":"13.4%","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.3%","standing":"low"},{"id":"revenueGrowth","label":"New business premium growth (YoY)","value":"16.8%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"5.2%","standing":"typical"},{"id":"eps","label":"Earnings per share","value":"₹22.4","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ASIANPAINT', '2026-06-30', false, '{"whatItDoes":"Asian Paints is India''s largest paint company, with more than a third of the decorative-paints market. It also sells waterproofing, adhesives and, increasingly, home-decor products such as kitchens and bathroom fittings.","financialHealth":"Asian Paints earns high returns on capital, carries almost no debt and pays steady dividends, helped by a very wide dealer and tinting-machine network. Growth and margins have come under pressure from well-funded new entrants and from swings in crude-linked raw-material costs.","thingsToWatch":["New competitors (Grasim''s Birla Opus, JSW Paints) are spending heavily to win share.","Titanium dioxide and other crude-linked inputs drive margins up and down.","Repainting is discretionary spending and softens when household budgets are tight."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.4 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"52.6","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"12.8","standing":"typical"},{"id":"roe","label":"Return on equity","value":"24.8%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.06","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"1.2%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"4.2%","standing":"low"},{"id":"profitMargin","label":"Net profit margin","value":"13.4%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('TITAN', '2026-06-30', false, '{"whatItDoes":"Titan, part of the Tata group, is best known for Tanishq, India''s largest branded jewellery chain, which brings in most of its sales. It also makes Titan and Fastrack watches, runs the Titan Eye+ eyewear chain, and has smaller businesses in sarees and fragrances.","financialHealth":"The jewellery business has grown fast as buyers shift from local goldsmiths to trusted brands. Titan earns healthy returns and carries modest debt, some of it tied to gold inventory. Profits can wobble when gold prices move sharply or when customers delay big purchases.","thingsToWatch":["Around 85% of revenue comes from jewellery, so gold-price swings and wedding-season demand matter a lot.","Sudden jumps in gold prices can cause customers to postpone buying.","The watches and eyewear businesses are much smaller and grow more slowly."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.1 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"84.2","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"24.6","standing":"high"},{"id":"roe","label":"Return on equity","value":"32.4%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"0.62","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"0.5%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"16.8%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"7.8%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ADANIENT', '2026-06-30', false, '{"whatItDoes":"Adani Enterprises is the flagship of the Adani group and acts as its incubator: it builds new businesses — airports, roads, data centres, green hydrogen and solar manufacturing, mining services — and spins the larger ones off as separate listed companies over time.","financialHealth":"The company is in a heavy investment phase, funding large projects with a mix of debt and equity, so borrowings are high and profits are lumpy as new businesses ramp up. It has faced questions from short-sellers and regulators about group governance and debt levels.","thingsToWatch":["Debt is high and several businesses are years away from generating steady profit.","The group''s governance and related-party dealings have drawn scrutiny from short-sellers and regulators.","Its market value swings sharply on group-wide news."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹2.8 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"78.4","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"5.8","standing":"typical"},{"id":"roe","label":"Return on equity","value":"9.2%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"1.34","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"0.1%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"14.6%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"4.2%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('GRASIM', '2026-06-30', false, '{"whatItDoes":"Grasim is an Aditya Birla group company that makes viscose fibre (used in textiles) and chemicals like caustic soda, and is the controlling shareholder of UltraTech Cement and Aditya Birla Capital. It has also spent heavily to launch a new paints business, Birla Opus.","financialHealth":"Most of Grasim''s underlying value sits in its stakes in UltraTech and Aditya Birla Capital, with the standalone fibre and chemicals business adding cyclical earnings. The recent paints launch involves large upfront spending that will weigh on profit for a few years before it pays off.","thingsToWatch":["The new paints business needs years and heavy spending to reach break-even, against an entrenched leader.","Viscose and caustic soda prices are cyclical and partly set by global markets.","As a holding company, its shares often trade below the value of its stakes."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.9 lakh crore","standing":"typical"},{"id":"peRatio","label":"P/E ratio","value":"24.2","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"1.8","standing":"low"},{"id":"roe","label":"Return on equity","value":"8.4%","standing":"low"},{"id":"debtToEquity","label":"Debt to equity","value":"0.48","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.6%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"9.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"6.8%","standing":"low"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ULTRACEMCO', '2026-06-30', false, '{"whatItDoes":"UltraTech Cement is India''s largest cement producer, with about a third of the country''s capacity, and is part of the Aditya Birla group. It supplies builders, infrastructure projects and individual home-builders, and has grown both by building new plants and buying rivals.","financialHealth":"UltraTech is profitable and generates strong cash, though the steady stream of expansion and acquisitions keeps debt at a moderate level. Cement is regional and cyclical: prices and volumes depend on construction activity in each area, and energy is a big cost.","thingsToWatch":["Cement demand tracks housing and infrastructure spending, which can slow sharply.","Coal and pet coke prices feed directly into production costs.","A wave of industry consolidation has raised competition for acquisitions and, at times, price wars."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.4 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"42.6","standing":"high"},{"id":"pbRatio","label":"P/B ratio","value":"4.8","standing":"typical"},{"id":"roe","label":"Return on equity","value":"12.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.32","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.6%","standing":"low"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"9.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"10.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('BHARTIARTL', '2026-06-30', false, '{"whatItDoes":"Bharti Airtel is India''s second-largest mobile operator after Reliance Jio, and also runs large broadband, enterprise and data-centre businesses. Through the separately listed Airtel Africa, it is a major telecom player across 14 African countries.","financialHealth":"Profits have improved as the industry settled into three private players and tariffs rose, lifting revenue per user. The company still carries sizeable debt from buying spectrum, though it has been paying it down. Africa adds growth but also currency risk.","thingsToWatch":["Revenue per user needs to keep rising to justify the heavy investment in spectrum and networks.","The African business is exposed to currency swings in markets like Nigeria.","Regular spectrum auctions and network upgrades keep capital spending high."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹9.8 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"48.2","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"8.4","standing":"typical"},{"id":"roe","label":"Return on equity","value":"14.6%","standing":"high"},{"id":"debtToEquity","label":"Debt to equity","value":"1.42","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.6%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"12.4%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"13.8%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('LT', '2026-06-30', false, '{"whatItDoes":"Larsen & Toubro is India''s largest engineering and construction company, building roads, metros, ports, power plants, refineries and defence equipment across India and the Middle East. It also controls the listed IT firms LTIMindtree and LTTS and is starting green-energy and data-centre businesses.","financialHealth":"Earnings are driven by the order book: L&T has been winning large infrastructure and Middle East contracts, which supports steady revenue growth. Construction ties up cash in projects, so it carries working-capital debt. The IT subsidiaries add a high-margin, cash-generative layer.","thingsToWatch":["Results depend on the flow of new orders and on executing them without cost overruns or payment delays.","A big share of order inflow now comes from the Middle East, adding geographic concentration.","Government and state-owned clients can be slow to pay, tying up working capital."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹5.2 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"34.8","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"5.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"16.8%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"1.12","standing":"high"},{"id":"dividendYield","label":"Dividend yield","value":"0.9%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"14.2%","standing":"high"},{"id":"profitMargin","label":"Net profit margin","value":"7.4%","standing":"typical"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('ADANIPORTS', '2026-06-30', false, '{"whatItDoes":"Adani Ports is India''s largest private port operator, handling roughly a quarter of the country''s sea cargo through Mundra and around a dozen other ports. It also runs a logistics arm (rail, warehousing) and has taken stakes in ports overseas, including in Israel and Sri Lanka.","financialHealth":"Ports are a high-margin, fairly steady infrastructure business, and Adani Ports has grown cargo volumes faster than the industry. It carries a meaningful amount of debt from acquisitions and expansion, and its shares move with news about the wider Adani group.","thingsToWatch":["Cargo volumes track India''s trade and the global economy.","Debt is significant and part of it is in foreign currency.","As part of the Adani group, its share price reacts to group-wide governance and debt news."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹3.1 lakh crore","standing":"high"},{"id":"peRatio","label":"P/E ratio","value":"28.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"4.2","standing":"typical"},{"id":"roe","label":"Return on equity","value":"17.4%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.82","standing":"typical"},{"id":"dividendYield","label":"Dividend yield","value":"0.7%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"13.6%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"26.8%","standing":"high"}]'::jsonb);
insert into fundamentals (symbol, as_of, generated, breakdown, metrics) values ('APOLLOHOSP', '2026-06-30', false, '{"whatItDoes":"Apollo Hospitals runs one of India''s largest chains of private hospitals, alongside the Apollo Pharmacy retail chain and Apollo 24/7, a digital health and online-pharmacy platform. Hospitals provide most of the profit; the digital arm is still loss-making as it scales.","financialHealth":"The hospital business is profitable and improving as occupancy and revenue per bed rise, and the mature pharmacy chain adds steady sales. Reported profit is held back by investment in the digital health platform. Debt is moderate and mostly tied to building new hospitals.","thingsToWatch":["Adding hospital beds is expensive and takes a few years to fill, weighing on returns in the meantime.","The digital health arm continues to lose money while it builds scale.","Doctor pay and medical-supply costs are steady upward pressures."]}'::jsonb, '[{"id":"marketCap","label":"Market cap","value":"₹1.1 lakh crore","standing":"low"},{"id":"peRatio","label":"P/E ratio","value":"68.4","standing":"typical"},{"id":"pbRatio","label":"P/B ratio","value":"11.6","standing":"typical"},{"id":"roe","label":"Return on equity","value":"16.8%","standing":"typical"},{"id":"debtToEquity","label":"Debt to equity","value":"0.38","standing":"low"},{"id":"dividendYield","label":"Dividend yield","value":"0.4%","standing":"typical"},{"id":"revenueGrowth","label":"Revenue growth (YoY)","value":"14.8%","standing":"typical"},{"id":"profitMargin","label":"Net profit margin","value":"7.6%","standing":"low"}]'::jsonb);
